// Example: update endpoint traffic split for canary deployment
const aiplatform = require('@google-cloud/aiplatform');
const client = new aiplatform.v1.EndpointServiceClient();

async function updateTrafficSplit(endpointPath, newModelId, trafficPercentage) {
  const [endpoint] = await client.getEndpoint({ name: endpointPath });

  const deployedModels = endpoint.deployedModels.map(model => ({
    id: model.id,
    ...model
  }));

  const trafficSplit = {
    '0': (100 - trafficPercentage) / 100, // existing model
    '1': trafficPercentage / 100          // new canary model
  };

  await client.deployModel({
    endpoint: endpointPath,
    deployedModel: {
      model: `projects/${project}/locations/${location}/models/${newModelId}`,
      displayName: `plant-a-canary-${Date.now()}`,
      trafficSplit
    }
  });
}
```

## Implementation Considerations
- Data versioning: Implement BigQuery table partitioning and Dataflow snapshot windows
- Model registry: Use Vertex AI Model Registry with semantic versioning per plant
- Drift monitoring: Set up custom metrics and Cloud Monitoring alerts
- Rollback automation: Cloud Functions triggered by drift thresholds
- Cost controls: Per-project budgets and Vertex AI endpoint autoscaling policies
